"""Preview the *procedural training data*, NOT samples generated by Sora.

Run: python3 -m scripts.dataset_v2 preview --output-dir /tmp/sora-dataset-v2
Generates 24 bilingual example PNGs and a contact sheet from PIL drawing.
These images must never be mistaken for inference from trained model weights.
"""
import argparse
import json
from pathlib import Path

from PIL import Image, ImageDraw
import torch

from src.pixel_dataset_v2 import CONCEPTS, synthetic_example_v2
from src.storage_paths import sora_run


def preview(output_dir,seed=42,split="validation",scale=8):
    root=Path(output_dir)
    root.mkdir(parents=True,exist_ok=False)
    size=32*scale
    image_sheet=Image.new("RGB",(4*size,6*(size+26)),"white")
    pen=ImageDraw.Draw(image_sheet)
    manifest=[]
    for index,(color,shape) in enumerate(CONCEPTS):
        for language_idx,language in enumerate(("en","ar")):
            # English and Arabic have matched semantics, though independent
            # sampled locations. This is dataset inspection, not model output.
            sample_seed=seed+index*37
            img,token,prompt,_=synthetic_example_v2(
                sample_seed,color=color,shape=shape,
                language=language,split=split,variant=0,
            )
            filename=f"{color}_{shape}_{language}.png"
            rgb=((img.permute(1,2,0).clamp(-1,1).numpy()+1)*127.5).round().astype("uint8")
            Image.fromarray(rgb).save(root/filename)
            row=2*(index//4)+language_idx
            col=index%4
            x,y=col*size,row*(size+26)
            with Image.open(root/filename) as thumb:
                image_sheet.paste(thumb.resize((size,size),Image.Resampling.NEAREST),(x,y))
            pen.text((x+4,y+size+4),f"{color} {shape} ({language})",fill="black")
            manifest.append({
                "file":filename,"prompt":prompt,"color":color,"shape":shape,
                "language":language,"seed":sample_seed,"split":split,
                "token_count":int((token!=0).sum()),
                "source":"procedural PIL training sample, NOT model inference",
            })
    image_sheet.save(root/"preview_grid.png")
    report={
        "schema_version":1,"dataset_version":"v2","samples":len(manifest),
        "classes":12,"languages":["en","ar"],"split":split,"seed":seed,
        "source":"procedural PIL training data; NOT diffusion-generated images",
        "items":manifest,
    }
    (root/"manifest.json").write_text(
        json.dumps(report,indent=2,ensure_ascii=False)+"\n",encoding="utf-8"
    )
    print(json.dumps({"preview_grid":str(root/"preview_grid.png"),
                      "manifest":str(root/"manifest.json"),
                      "images":len(manifest)}))
    return report


def main():
    parser=argparse.ArgumentParser()
    modes=parser.add_subparsers(dest="command",required=True)
    p=modes.add_parser("preview")
    p.add_argument("--output-dir",default=None)
    p.add_argument("--seed",type=int,default=42)
    p.add_argument("--split",choices=("train","validation"),default="validation")
    p.add_argument("--scale",type=int,default=8)
    args=parser.parse_args()
    if not 1 <= args.scale <= 20:
        parser.error("scale must be 1..20")
    preview(args.output_dir or sora_run("dataset-preview"),args.seed,args.split,args.scale)


if __name__=="__main__":
    main()
